when.set-body:
@{
            var r = context.Response.Body.As();
            var docs = (JArray)r["value"];
            var chunks = new JArray();
            foreach (var d in docs) {
                chunks.Add(new JObject(
                    new JProperty("chunk_no", d["chunk_no"]),
                    new JProperty("heading", d["heading"]),
                    new JProperty("version", d["version"]),
                    new JProperty("chunk_id", d["chunk_id"])));
            }
            JToken first = docs.Count > 0 ? docs[0] : null;
            return new JObject(
                new JProperty("articleId", context.Request.MatchedParameters["articleId"]),
                new JProperty("inIndex", docs.Count > 0),
                new JProperty("title", first != null ? first["title"] : null),
                new JProperty("version", first != null ? first["version"] : null),
                new JProperty("status", first != null ? first["status"] : null),
                new JProperty("lastPublished", first != null ? first["last_published"] : null),
                new JProperty("chunkCount", docs.Count),
                new JProperty("chunks", chunks)
            ).ToString();
        }
